The binary tree has root 6; 6 has left child 2 and right child 9; 2 has children 1 and 4; 9 has only a right child 12. What does `g(root)` print?

```c
#include <stdio.h>
struct N { int v; struct N *l, *r; };
int g(struct N *p){ if (!p) return 0; int s = p->v + g(p->l); printf("%d ", s); return s + g(p->r); }
int main(void){ struct N a={1,0,0}, b={4,0,0}, c={12,0,0}, d={2,&a,&b}, e={9,0,&c}, r={6,&d,&e}; g(&r); return 0; }
```

