What is the largest n for which `foo(n)` returns 4? (bar(n) = floor(log2 n).)

```c
#include <stdio.h>
int bar(int n){ if (n == 1) return 0; return 1 + bar(n/2); }
int foo(int n){ if (n == 1) return 1; return 1 + foo(bar(n)); }
int main(void){ int l=0; for (int n=1; n<200000; n++) if (foo(n)==4) l=n; printf("%d", l); return 0; }
```

What is printed? (Hint: find what f computes.)

```c
#include <stdio.h>
int f(int n){ if (n < 10) return n; return f(f(n/10) + n % 10); }
int main(void){ printf("%d", f(98765)); return 0; }
```

`d` tracks depth. What is printed?

```c
#include <stdio.h>
int f(int n){ static int d = 0; int r; d++; if (n <= 1) r = d; else r = f(n-1) + f(n-2); d--; return r; }
int main(void){ printf("%d", f(5)); return 0; }
```

What does `A(2,3)` return?

```c
#include <stdio.h>
int A(int m, int n){ if (m == 0) return n+1; if (n == 0) return A(m-1, 1); return A(m-1, A(m, n-1)); }
int main(void){ printf("%d", A(2,3)); return 0; }
```

What does `f(3)` return? (Order of evaluation of the operands of `+` is unspecified; calls are not interleaved.)

```c
#include <stdio.h>
int g = 0;
int f(int n){ if (n == 0) return 0; return f(n-1) * 10 + (++g); }
int main(void){ printf("%d", f(3)); return 0; }
```
